css:
.sheet{position:relative; overflow:visible; background:#fff; border-radius:20px}
.sheet>.doodle{position:absolute; z-index:3}
.doodle--btm{bottom:-14px; left:38%; width:34px}
.doodle--top{top:-8px; right:8%; width:30px}
.tri{position:absolute; width:12px; height:12px; background:#f39800;
  clip-path:polygon(50% 0,100% 100%,0 100%); top:-11px; left:12%}
.tri--l{background:#8dc21f; clip-path:polygon(0 50%,100% 0,100% 100%); top:calc(100% + 8px)}
